public int longestPalindrome(String s) {
        int[] count = new int[128];
        boolean hasSingle = false;
        for (char c : s.toCharArray()) {
            count[c]++;
        }
        int len = 0;
        for (int j : count) {
            if (j % 2 == 0) {
                len += j;
            } else {
                len += j - 1;
                hasSingle = true;
            }
        }
        return hasSingle ? len + 1 : len;
    }
